"use strict";$(function(){var n=$(".pageTop");n.hide(),$(window).scroll(function(){300<$(this).scrollTop()?n.fadeIn():n.fadeOut()}),n.click(function(){return $("body,html").animate({scrollTop:0},350),!1}),$(".nav-toggle").click(function(){$(this).toggleClass("opened"),$("#gnav").toggleClass("active")}),$("#gnav ul.navi li a").click(function(){$(".nav-toggle").toggleClass("opened"),$("#gnav").toggleClass("active")}),$(document).on("click",'a[href*="#"]',function(){var n=$("header").innerHeight(),t=$(this.hash);if(t.length)return t=t.offset().top-n,$("html,body").animate({scrollTop:t},400,"swing"),!1})});